insert into public.destinations (id, slug, name, tagline, description, best_time, highlights, image, featured, published, "order") values
  ('dest-kyrgyzstan', 'kyrgyzstan', '{"en":"Kyrgyzstan","ru":"Кыргызстан","ky":"Кыргызстан"}'::jsonb, '{"en":"Land of celestial mountains","ru":"Страна небесных гор","ky":"Асман тоолорунун өлкөсү"}'::jsonb, '{"en":"Ninety-four percent mountains, two thousand alpine lakes and a nomadic culture that still lives in the summer pastures. Kyrgyzstan is our home — and the place we know best.","ru":"Девяносто четыре процента гор, две тысячи высокогорных озёр и кочевая культура, которая всё ещё живёт на летних пастбищах. Кыргызстан — наш дом и место, которое мы знаем лучше всего.","ky":"Токсон төрт пайызы тоо, эки миң бийик тоолуу көл жана жайлоолордо дагы эле жашап келе жаткан көчмөн маданият. Кыргызстан — биздин үйүбүз жана эң жакшы билген жерибиз."}'::jsonb, '{"en":"June – September","ru":"Июнь – сентябрь","ky":"Июнь – сентябрь"}'::jsonb, '{"en":["Song-Kul & Issyk-Kul lakes","Yurt stays with herding families","Tian Shan treks","Silk Road heritage"],"ru":["Озёра Сон-Куль и Иссык-Куль","Юрты в семьях чабанов","Треккинг по Тянь-Шаню","Наследие Шёлкового пути"]}'::jsonb, 'https://images.unsplash.com/photo-1489421382202-f7ec0cfd96f7?auto=format&fit=crop&w=1600&q=75', true, true, 1),
  ('dest-uzbekistan', 'uzbekistan', '{"en":"Uzbekistan","ru":"Узбекистан","ky":"Өзбекстан"}'::jsonb, '{"en":"Blue domes of the Silk Road","ru":"Голубые купола Шёлкового пути","ky":"Жибек жолунун көк куполдору"}'::jsonb, '{"en":"Samarkand, Bukhara and Tashkent: madrasas covered in turquoise tiles, lively bazaars and the best plov in Central Asia — linked by fast, comfortable trains.","ru":"Самарканд, Бухара и Ташкент: медресе в бирюзовой мозаике, шумные базары и лучший плов Центральной Азии — и удобные скоростные поезда между городами.","ky":"Самарканд, Бухара жана Ташкент: көгүлтүр мозаикалуу медреселер, ызы-чуулуу базарлар жана Борбор Азиянын эң даамдуу палоосу — шаарлар ортосунда ылдам поезддер."}'::jsonb, '{"en":"March – June, September – November","ru":"Март – июнь, сентябрь – ноябрь","ky":"Март – июнь, сентябрь – ноябрь"}'::jsonb, '{"en":["Registan, Samarkand","Old town of Bukhara","Afrosiyob high-speed train","Uzbek cuisine"],"ru":["Регистан, Самарканд","Старый город Бухары","Скоростной поезд «Афросиаб»","Узбекская кухня"]}'::jsonb, 'https://images.unsplash.com/photo-1763144967763-2a8a98cb8431?auto=format&fit=crop&w=1600&q=75', true, true, 2),
  ('dest-kazakhstan', 'kazakhstan', '{"en":"Almaty, Kazakhstan","ru":"Алматы, Казахстан","ky":"Алматы, Казакстан"}'::jsonb, '{"en":"City at the foot of the mountains","ru":"Город у подножия гор","ky":"Тоо этегиндеги шаар"}'::jsonb, '{"en":"Almaty combines a lively city with wild nature an hour away: the turquoise Big Almaty Lake, the red Charyn Canyon and the peaks of the Ile-Alatau.","ru":"Алматы — это живой город и дикая природа в часе езды: бирюзовое Большое Алматинское озеро, красный Чарынский каньон и вершины Иле-Алатау.","ky":"Алматы — жандуу шаар жана бир сааттык аралыктагы жапайы табият: көгүлтүр Чоң Алматы көлү, кызыл Чарын капчыгайы жана Иле-Алатоо чокулары."}'::jsonb, '{"en":"Year-round; lakes best May – October","ru":"Круглый год; озёра — май – октябрь","ky":"Жыл бою; көлдөр — май – октябрь"}'::jsonb, '{"en":["Charyn Canyon","Big Almaty Lake","Kok-Tobe","Medeu & Shymbulak"],"ru":["Чарынский каньон","Большое Алматинское озеро","Кок-Тобе","Медеу и Шымбулак"]}'::jsonb, 'https://images.unsplash.com/photo-1572940734104-684309ed7ac9?auto=format&fit=crop&w=1600&q=75', true, true, 3),
  ('dest-turkey', 'turkey', '{"en":"Türkiye","ru":"Турция","ky":"Түркия"}'::jsonb, '{"en":"Where continents meet","ru":"Там, где встречаются континенты","ky":"Континенттер кезиккен жер"}'::jsonb, '{"en":"Byzantine mosaics, Ottoman palaces and the otherworldly valleys of Cappadocia — a country of layered histories and generous tables.","ru":"Византийские мозаики, османские дворцы и неземные долины Каппадокии — страна многослойной истории и щедрых застолий.","ky":"Византия мозаикалары, осмон сарайлары жана Каппадокиянын укмуштуудай өрөөндөрү — бай тарыхтуу жана берешен дасторкондуу өлкө."}'::jsonb, '{"en":"April – June, September – October","ru":"Апрель – июнь, сентябрь – октябрь","ky":"Апрель – июнь, сентябрь – октябрь"}'::jsonb, '{"en":["Hot-air balloons over Cappadocia","Istanbul’s Old City","Bosphorus cruises","Cave hotels"],"ru":["Воздушные шары над Каппадокией","Старый город Стамбула","Прогулки по Босфору","Пещерные отели"]}'::jsonb, 'https://images.unsplash.com/photo-1530789253388-582c481c54b0?auto=format&fit=crop&w=1600&q=75', true, false, 2),
  ('dest-italy', 'italy', '{"en":"Italy","ru":"Италия","ky":"Италия"}'::jsonb, '{"en":"La dolce vita, slowly","ru":"Dolce vita без спешки","ky":"Шашылбаган dolce vita"}'::jsonb, '{"en":"From the ruins of Rome to the canals of Venice and the pale peaks of the Dolomites, Italy rewards travellers who take their time.","ru":"От руин Рима до каналов Венеции и светлых вершин Доломитов — Италия раскрывается тем, кто не торопится.","ky":"Римдин урандыларынан Венециянын каналдарына жана Доломиттердин ак чокуларына чейин — Италия шашылбагандарга ачылат."}'::jsonb, '{"en":"May – June, September – October","ru":"Май – июнь, сентябрь – октябрь","ky":"Май – июнь, сентябрь – октябрь"}'::jsonb, '{"en":["Colosseum & Vatican","Venice by gondola","Dolomites hiking","Regional cooking classes"],"ru":["Колизей и Ватикан","Венеция на гондоле","Походы в Доломитах","Кулинарные классы"]}'::jsonb, 'https://images.unsplash.com/photo-1523906834658-6e24ef2386f9?auto=format&fit=crop&w=1600&q=75', true, false, 3),
  ('dest-switzerland', 'switzerland', '{"en":"Switzerland","ru":"Швейцария","ky":"Швейцария"}'::jsonb, '{"en":"Alpine perfection","ru":"Альпийское совершенство","ky":"Альп кемчиликсиздиги"}'::jsonb, '{"en":"Panoramic railways, glacier-fed lakes and villages that look painted onto the mountainside. Precision and wilderness in perfect balance.","ru":"Панорамные железные дороги, ледниковые озёра и деревни, будто нарисованные на склонах гор. Точность и дикая природа в идеальном балансе.","ky":"Панорамалык темир жолдор, мөңгү көлдөрү жана тоо боорлоруна тартылгандай айылдар. Тактык менен жапайы табияттын эң сонун тең салмагы."}'::jsonb, '{"en":"June – September, December – March","ru":"Июнь – сентябрь, декабрь – март","ky":"Июнь – сентябрь, декабрь – март"}'::jsonb, '{"en":["Glacier Express","Matterhorn & Zermatt","Lauterbrunnen valley","Lake Lucerne"],"ru":["«Ледниковый экспресс»","Маттерхорн и Церматт","Долина Лаутербруннен","Люцернское озеро"]}'::jsonb, 'https://images.unsplash.com/photo-1530122037265-a5f1f91d3b99?auto=format&fit=crop&w=1600&q=75', true, false, 4),
  ('dest-japan', 'japan', '{"en":"Japan","ru":"Япония","ky":"Япония"}'::jsonb, '{"en":"Tradition in bloom","ru":"Традиции в цвету","ky":"Гүлдөгөн салттар"}'::jsonb, '{"en":"Ancient temples beside neon cities, meticulous craft and seasonal beauty — from cherry blossoms in spring to fiery maples in autumn.","ru":"Древние храмы рядом с неоновыми мегаполисами, безупречное ремесло и сезонная красота — от сакуры весной до огненных клёнов осенью.","ky":"Неон шаарлардын жанындагы байыркы ибадатканалар, кылдат кол өнөрчүлүк жана мезгилдик сулуулук — жазында сакурадан күзүндө кызыл клёндорго чейин."}'::jsonb, '{"en":"Late March – April, November","ru":"Конец марта – апрель, ноябрь","ky":"Март аягы – апрель, ноябрь"}'::jsonb, '{"en":["Kyoto temples","Ryokan & onsen","Mount Fuji views","Tokyo food culture"],"ru":["Храмы Киото","Рёкан и онсэн","Виды на Фудзи","Гастрокультура Токио"]}'::jsonb, 'https://images.unsplash.com/photo-1545569341-9eb8b30979d9?auto=format&fit=crop&w=1600&q=75', true, false, 5),
  ('dest-uae', 'uae', '{"en":"United Arab Emirates","ru":"ОАЭ","ky":"БАЭ"}'::jsonb, '{"en":"Desert meets skyline","ru":"Пустыня и небоскрёбы","ky":"Чөл жана асман тиреген имараттар"}'::jsonb, '{"en":"Golden dunes, record-breaking architecture and warm winter sun — an effortless escape with impeccable service.","ru":"Золотые дюны, рекордная архитектура и тёплое зимнее солнце — лёгкий отдых с безупречным сервисом.","ky":"Алтын кумдар, рекорддук архитектура жана кышкы жылуу күн — кемчиликсиз тейлөө менен жеңил эс алуу."}'::jsonb, '{"en":"October – April","ru":"Октябрь – апрель","ky":"Октябрь – апрель"}'::jsonb, '{"en":["Private desert dinners","Burj Khalifa","Beach resorts","Abu Dhabi’s Grand Mosque"],"ru":["Частные ужины в пустыне","Бурдж-Халифа","Пляжные курорты","Большая мечеть Абу-Даби"]}'::jsonb, 'https://images.unsplash.com/photo-1512453979798-5ea266f8880c?auto=format&fit=crop&w=1600&q=75', false, false, 6)
insert into public.guides (id, name, role, bio, languages, photo, published, "order") values
  ('guide-azamat-t', 'Azamat T.', '{"en":"Mountain & culture guide","ru":"Горный и культурный гид"}'::jsonb, '{"en":"Grew up in a herding family in Naryn and has guided horse journeys for over a decade.","ru":"Вырос в семье чабанов в Нарыне и водит конные маршруты более десяти лет."}'::jsonb, '["English","Русский","Кыргызча"]'::jsonb, 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=400&q=75', true, 1),
  ('guide-aigerim-s', 'Aigerim S.', '{"en":"Regional guide, Issyk-Kul","ru":"Региональный гид, Иссык-Куль"}'::jsonb, '{"en":"Karakol native and amateur historian with a passion for Silk Road stories.","ru":"Уроженка Каракола и историк-любитель, влюблённая в истории Шёлкового пути."}'::jsonb, '["English","Русский","Кыргызча","Deutsch"]'::jsonb, 'https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&w=400&q=75', true, 2),
  ('guide-bakyt-m', 'Bakyt M.', '{"en":"Certified mountain guide","ru":"Сертифицированный горный гид"}'::jsonb, '{"en":"Wilderness first responder who has crossed every major pass in the Terskey range.","ru":"Спасатель с подготовкой по первой помощи, прошёл все основные перевалы хребта Терскей."}'::jsonb, '["English","Русский","Кыргызча"]'::jsonb, 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=400&q=75', true, 3),
  ('guide-nurlan-k', 'Nurlan K.', '{"en":"Historian & private guide","ru":"Историк и частный гид"}'::jsonb, '{"en":"Archaeology graduate who has worked on Silk Road excavation sites in Chuy valley.","ru":"Археолог по образованию, участвовал в раскопках на Шёлковом пути в Чуйской долине."}'::jsonb, '["English","Русский","Кыргызча"]'::jsonb, 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?auto=format&fit=crop&w=400&q=75', true, 4),
  ('guide-emre-d', 'Emre D.', '{"en":"Licensed guide, Türkiye","ru":"Лицензированный гид, Турция"}'::jsonb, '{"en":"Art historian specialising in Byzantine mosaics and Ottoman architecture.","ru":"Искусствовед, специалист по византийским мозаикам и османской архитектуре."}'::jsonb, '["English","Türkçe","Русский"]'::jsonb, 'https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?auto=format&fit=crop&w=400&q=75', false, 5),
  ('guide-giulia-r', 'Giulia R.', '{"en":"Italy travel designer","ru":"Дизайнер путешествий по Италии"}'::jsonb, '{"en":"Roman by birth, mountaineer by choice — she designs every Italian itinerary we run.","ru":"Римлянка по рождению и альпинистка по призванию — разрабатывает все наши итальянские маршруты."}'::jsonb, '["English","Italiano","Русский"]'::jsonb, 'https://images.unsplash.com/photo-1438761681033-6461ffad8d80?auto=format&fit=crop&w=400&q=75', false, 6),
  ('guide-lukas-b', 'Lukas B.', '{"en":"Alpine tour leader","ru":"Руководитель альпийских туров"}'::jsonb, '{"en":"Swiss mountain leader and former ski instructor from the Bernese Oberland.","ru":"Швейцарский горный гид и бывший инструктор по лыжам из Бернского Оберланда."}'::jsonb, '["English","Deutsch","Français"]'::jsonb, 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=400&q=75', false, 7),
  ('guide-haruka-n', 'Haruka N.', '{"en":"Japan tour leader","ru":"Руководитель туров по Японии"}'::jsonb, '{"en":"Kyoto-raised guide and certified tea-ceremony practitioner.","ru":"Гид из Киото и сертифицированный мастер чайной церемонии."}'::jsonb, '["English","日本語"]'::jsonb, 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?auto=format&fit=crop&w=400&q=75', false, 8),
  ('guide-omar-h', 'Omar H.', '{"en":"Private host, UAE","ru":"Персональный хост, ОАЭ"}'::jsonb, '{"en":"Emirati host who loves sharing Bedouin traditions alongside the modern city.","ru":"Эмиратский хост, который с любовью рассказывает о традициях бедуинов и современном городе."}'::jsonb, '["English","العربية"]'::jsonb, 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?auto=format&fit=crop&w=400&q=75', false, 9)
insert into public.tours (id, slug, title, location, summary, description, highlights, included, excluded, itinerary, places, guide_id, images, dates, group_size, destination, category, type, difficulty, duration_days, price, rating, reviews_count, popularity, featured, published) values
  ('tour-song-kul', 'song-kul-nomad-journey', '{"en":"Song-Kul Nomad Journey","ru":"Кочевое путешествие на Сон-Куль","ky":"Соң-Көлгө көчмөн саякаты"}'::jsonb, '{"en":"Naryn region, Kyrgyzstan","ru":"Нарынская область, Кыргызстан","ky":"Нарын облусу, Кыргызстан"}'::jsonb, '{"en":"Ride across high pastures to a 3,016 m alpine lake and sleep in a family yurt camp under an ocean of stars.","ru":"Верхом по высокогорным пастбищам к озеру на высоте 3016 м и ночёвки в семейном юртовом лагере под звёздами.","ky":"Бийик жайлоолор аркылуу 3016 м бийиктиктеги көлгө ат менен барып, жылдыздар астында боз үйдө түнөйсүз."}'::jsonb, '{"en":"Song-Kul is where Kyrgyz nomadic life still follows the rhythm of the seasons. Over six days you will cross the Kalmak-Ashuu pass, ride with a local horseman to the lake shore, learn how a yurt is assembled, taste fresh kymyz and watch eagle hunters at work. Evenings belong to the fire, to komuz music and to a night sky with almost no light pollution.","ru":"Сон-Куль — место, где кочевая жизнь всё ещё следует ритму сезонов. За шесть дней вы пересечёте перевал Калмак-Ашуу, проедете верхом с местным табунщиком к берегу озера, узнаете, как собирается юрта, попробуете свежий кымыз и увидите работу беркутчи. Вечера — у костра, под звуки комуза и небо почти без засветки."}'::jsonb, '{"en":["Two nights in a family yurt camp","Horse riding with a local herder","Eagle hunting demonstration","Komuz music evening"],"ru":["Две ночи в семейном юртовом лагере","Конная прогулка с местным чабаном","Показ охоты с беркутом","Вечер музыки на комузе"]}'::jsonb, '{"en":["All ground transport in a comfortable 4×4","English- or Russian-speaking guide","Yurt camp and guesthouse accommodation","All meals outside Bishkek","Horse riding and cultural workshops"],"ru":["Весь транспорт на комфортабельном внедорожнике","Англо- или русскоговорящий гид","Проживание в юртах и гостевых домах","Питание за пределами Бишкека","Конные прогулки и мастер-классы"]}'::jsonb, '{"en":["International flights","Travel insurance","Dinner in Bishkek","Personal expenses and tips"],"ru":["Международные перелёты","Страховка","Ужин в Бишкеке","Личные расходы и чаевые"]}'::jsonb, '[{"day":"1","stop":"Bishkek","title":{"en":"Arrival in Bishkek","ru":"Прибытие в Бишкек"},"text":{"en":"Airport transfer, welcome dinner and trip briefing with your guide.","ru":"Трансфер из аэропорта, приветственный ужин и брифинг с гидом."}},{"day":"2","stop":"Kochkor","title":{"en":"Kochkor felt workshops","ru":"Войлочные мастерские Кочкора"},"text":{"en":"Drive along the Chuy valley to Kochkor. Shyrdak felt-making with a women’s cooperative and a homestay night.","ru":"Дорога по Чуйской долине в Кочкор. Изготовление шырдака с женским кооперативом и ночь в гостевом доме."}},{"day":"3–4","stop":"Song-Kul","title":{"en":"Over the pass to Song-Kul","ru":"Через перевал к Сон-Кулю"},"text":{"en":"Cross Kalmak-Ashuu (3,446 m), settle into the yurt camp and spend a full day riding the shoreline.","ru":"Перевал Калмак-Ашуу (3446 м), заселение в юрты и целый день конных прогулок вдоль берега."}},{"day":"5","stop":"Kyzart","title":{"en":"Eagle hunters & descent","ru":"Беркутчи и спуск"},"text":{"en":"Meet an eagle hunter, then descend via Kyzart to a village guesthouse.","ru":"Встреча с беркутчи и спуск через Кызарт в сельский гостевой дом."}},{"day":"6","stop":"Bishkek","title":{"en":"Return to Bishkek","ru":"Возвращение в Бишкек"},"text":{"en":"Scenic drive back with a stop at Burana tower. Farewell lunch.","ru":"Живописная дорога обратно с остановкой у башни Бурана. Прощальный обед."}}]'::jsonb, '["Bishkek","Kochkor","Song-Kul","Kyzart"]'::jsonb, 'guide-azamat-t', '["https://images.unsplash.com/photo-1489421382202-f7ec0cfd96f7?auto=format&fit=crop&w=1600&q=75","https://images.unsplash.com/photo-1783303391423-0085f18dc50e?auto=format&fit=crop&w=1600&q=75","https://images.unsplash.com/photo-1773658949441-76d4fb11412f?auto=format&fit=crop&w=1600&q=75","https://images.unsplash.com/photo-1759477141176-03365000b5e8?auto=format&fit=crop&w=1600&q=75","https://images.unsplash.com/photo-1694167232441-fd7a2c238d19?auto=format&fit=crop&w=1600&q=75"]'::jsonb, '["2027-06-05","2027-06-12","2027-06-19","2027-06-26","2027-07-03","2027-07-10","2027-07-17","2027-07-24","2027-07-31","2027-08-07","2027-08-14","2027-08-21","2027-08-28","2027-09-04"]'::jsonb, '{"min":4,"max":12}'::jsonb, 'kyrgyzstan', 'cultural', 'group', 'moderate', 6, 890, 4.9, 128, 98, true, true),
  ('tour-issyk-kul', 'issyk-kul-karakol-escape', '{"en":"Issyk-Kul & Karakol Escape","ru":"Иссык-Куль и Каракол","ky":"Ысык-Көл жана Каракол"}'::jsonb, '{"en":"Issyk-Kul region, Kyrgyzstan","ru":"Иссык-Кульская область, Кыргызстан","ky":"Ысык-Көл облусу, Кыргызстан"}'::jsonb, '{"en":"The “pearl of Central Asia”: red-rock canyons, a warm alpine sea, Dungan cuisine and the spruce valleys of Karakol.","ru":"«Жемчужина Центральной Азии»: красные каньоны, тёплое горное озеро, дунганская кухня и еловые ущелья Каракола.","ky":"«Борбор Азиянын бермети»: кызыл зоокалар, жылуу тоо көлү, дунган ашканасы жана Караколдун карагай капчыгайлары."}'::jsonb, '{"en":"A gentle introduction to Kyrgyzstan that circles the world’s second-largest alpine lake. Walk through the surreal Skazka “Fairy Tale” canyon, swim in mineral-rich water framed by snowy peaks, visit the wooden Holy Trinity Cathedral and the Dungan mosque in Karakol, and hike to Jeti-Oguz’s Seven Bulls rocks.","ru":"Мягкое знакомство с Кыргызстаном вокруг второго по величине высокогорного озера мира. Прогулка по каньону «Сказка», купание в минерализованной воде на фоне снежных вершин, деревянный Свято-Троицкий собор и дунганская мечеть в Караколе, поход к скалам «Семь быков» в Джети-Огузе."}'::jsonb, '{"en":["Skazka “Fairy Tale” canyon","Swimming in Issyk-Kul","Dungan family dinner","Jeti-Oguz red rocks"],"ru":["Каньон «Сказка»","Купание в Иссык-Куле","Ужин в дунганской семье","Красные скалы Джети-Огуза"]}'::jsonb, '{"en":["Comfortable minivan transport","Professional guide","Hotels, guesthouse and yurt camp","Breakfasts and three dinners","Entrance fees"],"ru":["Комфортабельный минивэн","Профессиональный гид","Отели, гостевой дом и юрты","Завтраки и три ужина","Входные билеты"]}'::jsonb, '{"en":["Flights","Travel insurance","Lunches","Optional horse riding"],"ru":["Перелёты","Страховка","Обеды","Конные прогулки по желанию"]}'::jsonb, '[{"day":"1","stop":"Bishkek","title":{"en":"Bishkek to Cholpon-Ata","ru":"Бишкек — Чолпон-Ата"},"text":{"en":"Drive to the north shore, visit the petroglyph field and enjoy a sunset swim.","ru":"Дорога на северный берег, поле петроглифов и купание на закате."}},{"day":"2","stop":"Karakol","title":{"en":"Karakol old town","ru":"Старый Каракол"},"text":{"en":"Wooden cathedral, Dungan mosque and a home-cooked ashlyan-fu lunch.","ru":"Деревянный собор, дунганская мечеть и домашний ашлямфу на обед."}},{"day":"3","stop":"Jeti-Oguz","title":{"en":"Jeti-Oguz valley","ru":"Ущелье Джети-Огуз"},"text":{"en":"Easy hike to the Valley of Flowers viewpoint and the Broken Heart rock.","ru":"Лёгкий поход к Долине цветов и скале «Разбитое сердце»."}},{"day":"4","stop":"Skazka","title":{"en":"South shore canyons","ru":"Каньоны южного берега"},"text":{"en":"Skazka canyon at golden hour and a night in a lakeside yurt camp.","ru":"Каньон «Сказка» в золотой час и ночь в юртах на берегу."}},{"day":"5","stop":"Bishkek","title":{"en":"Return via Boom gorge","ru":"Возвращение через Боомское ущелье"},"text":{"en":"Morning swim and drive back to Bishkek.","ru":"Утреннее купание и дорога в Бишкек."}}]'::jsonb, '["Bishkek","Karakol","Jeti-Oguz","Skazka"]'::jsonb, 'guide-aigerim-s', '["https://images.unsplash.com/photo-1626767507695-7165523a5372?auto=format&fit=crop&w=1600&q=75","https://images.unsplash.com/photo-1551189783-e226306fd8a1?auto=format&fit=crop&w=1600&q=75","https://images.unsplash.com/photo-1675157935570-e04938711f1e?auto=format&fit=crop&w=1600&q=75","https://images.unsplash.com/photo-1718750041559-b7369ba7b55a?auto=format&fit=crop&w=1600&q=75","https://images.unsplash.com/photo-1608497735578-11912e18ed9f?auto=format&fit=crop&w=1600&q=75"]'::jsonb, '["2027-06-04","2027-06-11","2027-06-18","2027-06-25","2027-07-02","2027-07-09","2027-07-16","2027-07-23","2027-07-30","2027-08-06","2027-08-13","2027-08-20","2027-08-27","2027-09-03"]'::jsonb, '{"min":2,"max":14}'::jsonb, 'kyrgyzstan', 'nature', 'group', 'easy', 5, 740, 4.8, 96, 94, true, true),
  ('tour-ala-kul', 'ala-kul-alpine-lake-trek', '{"en":"Ala-Kul Alpine Lake Trek","ru":"Треккинг к озеру Ала-Куль","ky":"Ала-Көлгө жөө жүрүш"}'::jsonb, '{"en":"Terskey Ala-Too, Kyrgyzstan","ru":"Терскей Ала-Тоо, Кыргызстан","ky":"Тескей Ала-Тоо, Кыргызстан"}'::jsonb, '{"en":"A classic Tian Shan trek over a 3,860 m pass to a turquoise glacial lake, finishing in the hot springs of Altyn-Arashan.","ru":"Классический тянь-шаньский маршрут через перевал 3860 м к бирюзовому ледниковому озеру с финалом в горячих источниках Алтын-Арашана.","ky":"3860 м ашуу аркылуу көгүлтүр мөңгү көлүнө чейин, Алтын-Арашандын ысык булактарында аяктаган классикалык Тянь-Шань маршруту."}'::jsonb, '{"en":"This is the trek that put Karakol on the map for hikers. Climb through spruce forest and moraine to Ala-Kul, a lake so intensely blue it looks painted, cross the Ala-Kul pass with views of Palatka peak, and descend to soak in natural hot springs. Porters and horses carry the heavy gear; you carry a light day pack.","ru":"Маршрут, благодаря которому Каракол узнали треккеры всего мира. Подъём через ельник и морену к Ала-Кулю — озеру невероятной синевы, переход через одноимённый перевал с видом на пик Палатка и спуск к природным горячим источникам. Тяжёлое снаряжение везут лошади — у вас только лёгкий рюкзак."}'::jsonb, '{"en":["Ala-Kul lake at 3,532 m","Panoramic pass at 3,860 m","Altyn-Arashan hot springs","Horse support for gear"],"ru":["Озеро Ала-Куль на 3532 м","Панорамный перевал 3860 м","Горячие источники Алтын-Арашан","Лошади для снаряжения"]}'::jsonb, '{"en":["Certified mountain guide","Tents, mats and kitchen equipment","All meals on trek","Pack horses","National park fees"],"ru":["Сертифицированный горный гид","Палатки, коврики и кухня","Питание на маршруте","Вьючные лошади","Сборы нацпарка"]}'::jsonb, '{"en":["Sleeping bag (rental available)","Transfer to Karakol","Insurance covering trekking to 4,000 m"],"ru":["Спальный мешок (можно арендовать)","Трансфер до Каракола","Страховка с покрытием треккинга до 4000 м"]}'::jsonb, '[{"day":"1","stop":"Karakol","title":{"en":"Karakol gorge to Sirota","ru":"Каракольское ущелье — Сирота"},"text":{"en":"Trek through spruce forest to camp at 2,900 m.","ru":"Переход через ельник к лагерю на 2900 м."}},{"day":"2","stop":"Ala-Kul","title":{"en":"Climb to Ala-Kul","ru":"Подъём к Ала-Кулю"},"text":{"en":"Steep ascent past waterfalls to the lake shore. Sunset over the glacier.","ru":"Крутой подъём мимо водопадов к берегу озера. Закат над ледником."}},{"day":"3","stop":"Altyn-Arashan","title":{"en":"Over the pass","ru":"Через перевал"},"text":{"en":"Cross the 3,860 m pass and descend to the Altyn-Arashan hot springs.","ru":"Перевал 3860 м и спуск к горячим источникам Алтын-Арашан."}},{"day":"4","stop":"Karakol","title":{"en":"Valley walk out","ru":"Выход по долине"},"text":{"en":"Morning soak, then walk out along the river and transfer to Karakol.","ru":"Утреннее купание в источниках и выход вдоль реки, трансфер в Каракол."}}]'::jsonb, '["Karakol","Ala-Kul","Altyn-Arashan"]'::jsonb, 'guide-bakyt-m', '["https://images.unsplash.com/photo-1721901194224-d91f30cbeac5?auto=format&fit=crop&w=1600&q=75","https://images.unsplash.com/photo-1608497735578-11912e18ed9f?auto=format&fit=crop&w=1600&q=75","https://images.unsplash.com/photo-1642514805906-a8307e41c3d7?auto=format&fit=crop&w=1600&q=75","https://images.unsplash.com/photo-1610720684893-619cd7a5cde5?auto=format&fit=crop&w=1600&q=75"]'::jsonb, '["2027-07-03","2027-07-10","2027-07-17","2027-07-24","2027-07-31","2027-08-07","2027-08-14","2027-08-21","2027-08-28"]'::jsonb, '{"min":4,"max":10}'::jsonb, 'kyrgyzstan', 'mountain', 'group', 'challenging', 4, 560, 4.9, 74, 90, true, true),
  ('tour-silk-road', 'silk-road-heritage-tash-rabat', '{"en":"Silk Road Heritage: Tash Rabat","ru":"Наследие Шёлкового пути: Таш-Рабат","ky":"Жибек жолунун мурасы: Таш-Рабат"}'::jsonb, '{"en":"Chuy, Naryn & At-Bashy, Kyrgyzstan","ru":"Чуй, Нарын и Ат-Башы, Кыргызстан","ky":"Чүй, Нарын жана Ат-Башы, Кыргызстан"}'::jsonb, '{"en":"Follow caravan routes to a 15th-century stone caravanserai near the Chinese border, with private guiding throughout.","ru":"По караванным тропам к каменному караван-сараю XV века у китайской границы — с личным гидом на всём маршруте.","ky":"Кербен жолдору менен Кытай чек арасына жакын XV кылымдагы таш кербен сарайга — жеке гид менен."}'::jsonb, '{"en":"A private, unhurried journey through the history of the Great Silk Road in Kyrgyzstan. From the Burana tower and the ancient city of Balasagun to the remote stone caravanserai of Tash Rabat and the high plateau of Chatyr-Kul, every day mixes archaeology, landscapes and hospitality in local homes.","ru":"Неспешное частное путешествие по истории Великого Шёлкового пути в Кыргызстане. От башни Бурана и древнего Баласагуна до затерянного каменного караван-сарая Таш-Рабат и высокогорного плато Чатыр-Куль — каждый день объединяет археологию, пейзажи и гостеприимство местных семей."}'::jsonb, '{"en":["Burana tower & Balasagun","Night near Tash Rabat caravanserai","Chatyr-Kul high plateau","Private vehicle & guide"],"ru":["Башня Бурана и Баласагун","Ночь у караван-сарая Таш-Рабат","Плато Чатыр-Куль","Личный автомобиль и гид"]}'::jsonb, '{"en":["Private vehicle and driver","Private historian guide","Boutique hotels, guesthouses and yurts","Full board outside Bishkek","Border-zone permit"],"ru":["Личный автомобиль с водителем","Личный гид-историк","Бутик-отели, гостевые дома и юрты","Полный пансион за пределами Бишкека","Пропуск в погранзону"]}'::jsonb, '{"en":["Flights","Travel insurance","Alcoholic drinks"],"ru":["Перелёты","Страховка","Алкогольные напитки"]}'::jsonb, '[{"day":"1","stop":"Bishkek","title":{"en":"Bishkek","ru":"Бишкек"},"text":{"en":"Private transfer, Osh bazaar walk and dinner with a historian.","ru":"Индивидуальный трансфер, прогулка по Ошскому базару и ужин с историком."}},{"day":"2","stop":"Burana","title":{"en":"Burana & Balasagun","ru":"Бурана и Баласагун"},"text":{"en":"Explore the 11th-century minaret and the balbal stone field.","ru":"Минарет XI века и поле каменных балбалов."}},{"day":"3–4","stop":"Naryn","title":{"en":"Naryn & the Moon Canyon","ru":"Нарын и Лунный каньон"},"text":{"en":"Cross the Dolon pass, visit the Koshoy-Korgon fortress ruins.","ru":"Перевал Долон, руины крепости Кошой-Коргон."}},{"day":"5","stop":"Tash Rabat","title":{"en":"Tash Rabat","ru":"Таш-Рабат"},"text":{"en":"Arrive at the caravanserai and stay in a nearby yurt camp.","ru":"Караван-сарай и ночь в юртах неподалёку."}},{"day":"6","stop":"Chatyr-Kul","title":{"en":"Chatyr-Kul plateau","ru":"Плато Чатыр-Куль"},"text":{"en":"Day trip to the 3,530 m lake on the old caravan road.","ru":"Выезд к озеру на высоте 3530 м по старой караванной дороге."}},{"day":"7","stop":"Bishkek","title":{"en":"Return","ru":"Возвращение"},"text":{"en":"Drive back to Bishkek with stops for photography.","ru":"Дорога в Бишкек с фотостопами."}}]'::jsonb, '["Bishkek","Burana","Naryn","Tash Rabat","Chatyr-Kul"]'::jsonb, 'guide-nurlan-k', '["https://images.unsplash.com/photo-1758016861632-a1c04a567f34?auto=format&fit=crop&w=1600&q=75","https://images.unsplash.com/photo-1602529359787-ce7468eaf119?auto=format&fit=crop&w=1600&q=75","https://images.unsplash.com/photo-1689788648186-60a2b9e1ad71?auto=format&fit=crop&w=1600&q=75","https://images.unsplash.com/photo-1610720684893-619cd7a5cde5?auto=format&fit=crop&w=1600&q=75"]'::jsonb, '["2027-05-10","2027-06-14","2027-07-12","2027-08-16","2027-09-13"]'::jsonb, '{"min":1,"max":6}'::jsonb, 'kyrgyzstan', 'cultural', 'private', 'easy', 7, 1390, 4.8, 52, 82, false, true),
  ('tour-kg-luxury', 'kyrgyzstan-quiet-luxury', '{"en":"Kyrgyzstan in Quiet Luxury","ru":"Кыргызстан: тихая роскошь","ky":"Кыргызстан: жымжырт люкс"}'::jsonb, '{"en":"Bishkek, Issyk-Kul & Chon-Kemin","ru":"Бишкек, Иссык-Куль и Чон-Кемин","ky":"Бишкек, Ысык-Көл жана Чоң-Кемин"}'::jsonb, '{"en":"Design lodges, a private chef in the mountains, a helicopter-view of the Tian Shan and spa days by the lake.","ru":"Дизайнерские лоджи, личный шеф-повар в горах, Тянь-Шань с высоты и спа-дни у озера.","ky":"Дизайн лоджалары, тоодо жеке ашпозчу, Тянь-Шанга бийиктен көз салуу жана көл жээгинде спа күндөр."}'::jsonb, '{"en":"For travellers who want the wild beauty of Kyrgyzstan without giving up comfort. Stay in the best lodges and lakeside resorts, travel by private Land Cruiser, enjoy a scenic flight over the mountains (weather permitting), and dine on seasonal Kyrgyz cuisine prepared by a private chef in a luxury yurt.","ru":"Для тех, кто хочет увидеть дикую красоту Кыргызстана, не отказываясь от комфорта. Лучшие лоджи и курорты на берегу озера, личный Land Cruiser, обзорный полёт над горами (при подходящей погоде) и сезонная кыргызская кухня от личного шеф-повара в люкс-юрте."}'::jsonb, '{"en":["Private chef dinner in a luxury yurt","Scenic mountain flight","Lakeside spa resort","Private Land Cruiser"],"ru":["Ужин от шефа в люкс-юрте","Обзорный полёт над горами","Спа-курорт на берегу озера","Личный Land Cruiser"]}'::jsonb, '{"en":["Five-star and boutique accommodation","Private vehicle, driver and guide","All meals and selected wines","Scenic flight (weather permitting)","Spa treatments and yacht cruise"],"ru":["Пятизвёздочные и бутик-отели","Личный автомобиль, водитель и гид","Всё питание и избранные вина","Обзорный полёт (при погоде)","Спа-процедуры и яхта"]}'::jsonb, '{"en":["International flights","Travel insurance","Gratuities"],"ru":["Международные перелёты","Страховка","Чаевые"]}'::jsonb, '[{"day":"1–2","stop":"Bishkek","title":{"en":"Bishkek in style","ru":"Стильный Бишкек"},"text":{"en":"VIP arrival, boutique hotel, private gallery tour and tasting menu.","ru":"VIP-встреча, бутик-отель, частный тур по галереям и дегустационный ужин."}},{"day":"3–4","stop":"Chon-Kemin","title":{"en":"Chon-Kemin valley","ru":"Долина Чон-Кемин"},"text":{"en":"Eco-lodge, horse riding at your own pace, chef’s dinner in a luxury yurt.","ru":"Эко-лодж, конные прогулки в своём темпе, ужин от шефа в люкс-юрте."}},{"day":"5–7","stop":"Issyk-Kul","title":{"en":"Issyk-Kul resort","ru":"Курорт на Иссык-Куле"},"text":{"en":"Spa, private yacht cruise, scenic flight and Skazka canyon at sunset.","ru":"Спа, частная яхта, обзорный полёт и каньон «Сказка» на закате."}},{"day":"8","stop":"Bishkek","title":{"en":"Departure","ru":"Отъезд"},"text":{"en":"Private transfer to Manas airport.","ru":"Индивидуальный трансфер в аэропорт Манас."}}]'::jsonb, '["Bishkek","Chon-Kemin","Issyk-Kul"]'::jsonb, 'guide-aigerim-s', '["https://images.unsplash.com/photo-1606402179428-a57976d71fa4?auto=format&fit=crop&w=1600&q=75","https://images.unsplash.com/photo-1689788648186-60a2b9e1ad71?auto=format&fit=crop&w=1600&q=75","https://images.unsplash.com/photo-1626767507695-7165523a5372?auto=format&fit=crop&w=1600&q=75","https://images.unsplash.com/photo-1783303391423-0085f18dc50e?auto=format&fit=crop&w=1600&q=75"]'::jsonb, '["2027-05-20","2027-06-18","2027-07-16","2027-08-20","2027-09-17"]'::jsonb, '{"min":2,"max":6}'::jsonb, 'kyrgyzstan', 'luxury', 'private', 'easy', 8, 3450, 5, 31, 76, true, true),
  ('tour-cappadocia', 'istanbul-cappadocia-classic', '{"en":"Istanbul & Cappadocia Classic","ru":"Стамбул и Каппадокия","ky":"Стамбул жана Каппадокия"}'::jsonb, '{"en":"Istanbul & Göreme, Türkiye","ru":"Стамбул и Гёреме, Турция","ky":"Стамбул жана Гёреме, Түркия"}'::jsonb, '{"en":"Byzantine domes and Ottoman bazaars, then a sunrise balloon flight over the fairy chimneys of Cappadocia.","ru":"Византийские купола и османские базары, а затем полёт на воздушном шаре над «каменными грибами» Каппадокии.","ky":"Византия куполдору жана осмон базарлары, андан кийин Каппадокиянын таш мамыларынын үстүндө аба шарында учуу."}'::jsonb, '{"en":"Two of Türkiye’s most iconic landscapes in one week. Start in Istanbul with Hagia Sophia, the Blue Mosque, a private Bosphorus cruise and the Grand Bazaar, then fly to Cappadocia to stay in a cave hotel, hike the Rose Valley and drift above the valleys at sunrise.","ru":"Две самые узнаваемые локации Турции за одну неделю. Стамбул — Айя-София, Голубая мечеть, частная прогулка по Босфору и Гранд-базар; затем перелёт в Каппадокию: пещерный отель, Розовая долина и рассветный полёт на шаре."}'::jsonb, '{"en":["Sunrise hot-air balloon flight","Cave hotel in Göreme","Private Bosphorus cruise","Hagia Sophia & Blue Mosque"],"ru":["Полёт на шаре на рассвете","Пещерный отель в Гёреме","Частная прогулка по Босфору","Айя-София и Голубая мечеть"]}'::jsonb, '{"en":["4★ boutique and cave hotels","Domestic flight Istanbul–Kayseri","Balloon flight","Licensed English-speaking guide","Daily breakfast and four dinners"],"ru":["4★ бутик- и пещерные отели","Внутренний перелёт Стамбул–Кайсери","Полёт на шаре","Лицензированный гид","Завтраки и четыре ужина"]}'::jsonb, '{"en":["International flights","Türkiye visa (if required)","Travel insurance","Lunches"],"ru":["Международные перелёты","Виза (если нужна)","Страховка","Обеды"]}'::jsonb, '[{"day":"1","stop":"Istanbul","title":{"en":"Arrival in Istanbul","ru":"Прибытие в Стамбул"},"text":{"en":"Transfer to Sultanahmet, welcome dinner with a view of the Golden Horn.","ru":"Трансфер в Султанахмет, ужин с видом на Золотой Рог."}},{"day":"2–3","stop":"Istanbul","title":{"en":"Old City & Bosphorus","ru":"Старый город и Босфор"},"text":{"en":"Hagia Sophia, Topkapı, Grand Bazaar and a private sunset cruise.","ru":"Айя-София, Топкапы, Гранд-базар и частная прогулка на закате."}},{"day":"4","stop":"Göreme","title":{"en":"Fly to Cappadocia","ru":"Перелёт в Каппадокию"},"text":{"en":"Check in to a cave hotel, Göreme open-air museum.","ru":"Заселение в пещерный отель, музей под открытым небом Гёреме."}},{"day":"5","stop":"Göreme","title":{"en":"Balloons & Rose Valley","ru":"Шары и Розовая долина"},"text":{"en":"Sunrise balloon flight, afternoon hike through Rose Valley.","ru":"Полёт на шаре на рассвете, днём — поход по Розовой долине."}},{"day":"6","stop":"Derinkuyu","title":{"en":"Underground city","ru":"Подземный город"},"text":{"en":"Derinkuyu underground city and a pottery workshop in Avanos.","ru":"Подземный город Деринкую и гончарная мастерская в Аваносе."}},{"day":"7","stop":"Kayseri","title":{"en":"Departure","ru":"Отъезд"},"text":{"en":"Transfer to Kayseri airport.","ru":"Трансфер в аэропорт Кайсери."}}]'::jsonb, '["Istanbul","Göreme","Derinkuyu","Kayseri"]'::jsonb, 'guide-emre-d', '["https://images.unsplash.com/photo-1530789253388-582c481c54b0?auto=format&fit=crop&w=1600&q=75","https://images.unsplash.com/photo-1524231757912-21f4fe3a7200?auto=format&fit=crop&w=1600&q=75","https://images.unsplash.com/photo-1541432901042-2d8bd64b4a9b?auto=format&fit=crop&w=1600&q=75","https://images.unsplash.com/photo-1527838832700-5059252407fa?auto=format&fit=crop&w=1600&q=75"]'::jsonb, '["2027-04-12","2027-05-03","2027-05-24","2027-09-06","2027-09-27","2027-10-18"]'::jsonb, '{"min":4,"max":16}'::jsonb, 'turkey', 'cultural', 'group', 'easy', 7, 1690, 4.8, 143, 96, true, false),
  ('tour-italy', 'rome-venice-dolomites', '{"en":"Rome, Venice & the Dolomites","ru":"Рим, Венеция и Доломиты","ky":"Рим, Венеция жана Доломиттер"}'::jsonb, '{"en":"Rome, Venice & South Tyrol, Italy","ru":"Рим, Венеция и Южный Тироль, Италия","ky":"Рим, Венеция жана Түштүк Тироль, Италия"}'::jsonb, '{"en":"Ancient Rome, a palazzo stay on the Grand Canal and alpine hikes around Lago di Braies in the Dolomites.","ru":"Античный Рим, палаццо на Гранд-канале и горные прогулки вокруг озера Брайес в Доломитах.","ky":"Байыркы Рим, Чоң каналдагы палаццо жана Доломиттердеги Брайес көлүнүн айланасында тоо сейилдөөлөрү."}'::jsonb, '{"en":"Italy at its most cinematic. Skip-the-line access to the Colosseum and Vatican, a private cooking class in Trastevere, a gondola at dusk in Venice and three nights in a design hotel in the Dolomites with guided walks to alpine huts.","ru":"Самая кинематографичная Италия. Колизей и Ватикан без очередей, частный кулинарный класс в Трастевере, гондола на закате в Венеции и три ночи в дизайн-отеле в Доломитах с прогулками к альпийским хижинам."}'::jsonb, '{"en":["Skip-the-line Colosseum & Vatican","Grand Canal palazzo hotel","Lago di Braies at sunrise","Private cooking class"],"ru":["Колизей и Ватикан без очередей","Палаццо на Гранд-канале","Озеро Брайес на рассвете","Частный кулинарный класс"]}'::jsonb, '{"en":["Boutique & design hotels","First-class rail tickets","Private guides in Rome and Venice","Mountain guide in the Dolomites","Breakfasts and five dinners"],"ru":["Бутик- и дизайн-отели","Ж/д билеты первого класса","Частные гиды в Риме и Венеции","Горный гид в Доломитах","Завтраки и пять ужинов"]}'::jsonb, '{"en":["International flights","Schengen visa","City tourist taxes","Travel insurance"],"ru":["Международные перелёты","Шенгенская виза","Туристические сборы","Страховка"]}'::jsonb, '[{"day":"1–3","stop":"Rome","title":{"en":"Eternal Rome","ru":"Вечный Рим"},"text":{"en":"Colosseum, Forum, Vatican Museums and a Trastevere cooking class.",