  ('tour-swiss', 'swiss-alps-grand-panorama', '{"en":"Swiss Alps Grand Panorama","ru":"Большая панорама Швейцарских Альп","ky":"Швейцария Альптарынын чоң панорамасы"}'::jsonb, '{"en":"Lucerne, Lauterbrunnen & Zermatt","ru":"Люцерн, Лаутербруннен и Церматт","ky":"Люцерн, Лаутербруннен жана Церматт"}'::jsonb, '{"en":"Panoramic trains, the valley of 72 waterfalls and the Matterhorn at sunrise — Switzerland at a relaxed pace.","ru":"Панорамные поезда, долина 72 водопадов и Маттерхорн на рассвете — Швейцария в спокойном темпе.","ky":"Панорамалык поезддер, 72 шаркыратманын өрөөнү жана таң атканда Маттерхорн — шашылбаган Швейцария."}'::jsonb, '{"en":"A rail-and-trail journey through the heart of the Alps. Cruise Lake Lucerne, ride the cogwheel railway up Mount Pilatus, walk beneath the waterfalls of Lauterbrunnen, take the Glacier Express and wake up to the Matterhorn glowing pink at dawn in car-free Zermatt.","ru":"Путешествие по железной дороге и тропам через сердце Альп. Круиз по Люцернскому озеру, зубчатая железная дорога на Пилатус, водопады Лаутербруннена, «Ледниковый экспресс» и розовый Маттерхорн на рассвете в Церматте без машин."}'::jsonb, '{"en":["Glacier Express panoramic train","Lauterbrunnen waterfall valley","Matterhorn sunrise","Lake Lucerne cruise"],"ru":["Панорамный «Ледниковый экспресс»","Долина водопадов Лаутербруннен","Маттерхорн на рассвете","Круиз по Люцернскому озеру"]}'::jsonb, '{"en":["4★ alpine hotels","Swiss Travel Pass (1st class)","Glacier Express reservation","Tour leader","Breakfasts and three dinners"],"ru":["4★ альпийские отели","Swiss Travel Pass (1 класс)","Бронь «Ледникового экспресса»","Руководитель группы","Завтраки и три ужина"]}'::jsonb, '{"en":["International flights","Schengen visa","Lunches","Travel insurance"],"ru":["Международные перелёты","Шенгенская виза","Обеды","Страховка"]}'::jsonb, '[{"day":"1–2","stop":"Lucerne","title":{"en":"Lucerne & Pilatus","ru":"Люцерн и Пилатус"},"text":{"en":"Chapel Bridge, lake cruise and the world’s steepest cogwheel railway.","ru":"Капелльбрюкке, круиз по озеру и самая крутая зубчатая дорога в мире."}},{"day":"3–4","stop":"Lauterbrunnen","title":{"en":"Jungfrau region","ru":"Регион Юнгфрау"},"text":{"en":"Waterfall walks, Mürren village and views of the Eiger north face.","ru":"Прогулки у водопадов, деревня Мюррен и северная стена Эйгера."}},{"day":"5","stop":"Glacier Express","title":{"en":"Glacier Express","ru":"«Ледниковый экспресс»"},"text":{"en":"Panoramic train journey across 291 bridges to Zermatt.","ru":"Панорамный поезд через 291 мост в Церматт."}},{"day":"6–7","stop":"Zermatt","title":{"en":"Zermatt & Matterhorn","ru":"Церматт и Маттерхорн"},"text":{"en":"Gornergrat at sunrise, Five Lakes walk, farewell fondue.","ru":"Горнерграт на рассвете, тропа Пяти озёр, прощальное фондю."}}]'::jsonb, '["Lucerne","Lauterbrunnen","Glacier Express","Zermatt"]'::jsonb, 'guide-lukas-b', '["https://images.unsplash.com/photo-1530122037265-a5f1f91d3b99?auto=format&fit=crop&w=1600&q=75","https://images.unsplash.com/photo-1454496522488-7a8e488e8606?auto=format&fit=crop&w=1600&q=75","https://images.unsplash.com/photo-1519681393784-d120267933ba?auto=format&fit=crop&w=1600&q=75","https://images.unsplash.com/photo-1551882547-ff40c63fe5fa?auto=format&fit=crop&w=1600&q=75"]'::jsonb, '["2027-06-05","2027-06-26","2027-07-24","2027-08-21","2027-09-18"]'::jsonb, '{"min":4,"max":12}'::jsonb, 'switzerland', 'mountain', 'group', 'easy', 7, 3890, 4.9, 58, 85, false, false),
  ('tour-japan', 'japan-cherry-blossom-journey', '{"en":"Japan Cherry Blossom Journey","ru":"Япония в сезон сакуры","ky":"Сакура мезгилиндеги Япония"}'::jsonb, '{"en":"Tokyo, Hakone & Kyoto, Japan","ru":"Токио, Хаконэ и Киото, Япония","ky":"Токио, Хаконэ жана Киото, Япония"}'::jsonb, '{"en":"Neon Tokyo, a ryokan night with views of Mount Fuji and the temple gardens of Kyoto in full sakura bloom.","ru":"Неоновый Токио, ночь в рёкане с видом на Фудзи и храмовые сады Киото в цветении сакуры.","ky":"Неон Токио, Фудзи тоосу көрүнгөн рёканда бир түн жана сакура гүлдөгөн Киотонун ибадаткана бактары."}'::jsonb, '{"en":"Timed for peak cherry-blossom season. Explore Tokyo’s contrasts from Asakusa to Shibuya, soak in an onsen in Hakone with Fuji on the horizon, ride the shinkansen to Kyoto for geisha districts, bamboo groves and tea ceremony, and finish in Nara among the sacred deer.","ru":"Маршрут приурочен к пику цветения сакуры. Контрасты Токио от Асакусы до Сибуи, онсэн в Хаконэ с видом на Фудзи, синкансэн в Киото — кварталы гейш, бамбуковая роща, чайная церемония — и финал в Наре среди священных оленей."}'::jsonb, '{"en":["Ryokan stay with onsen in Hakone","Shinkansen bullet train","Private tea ceremony","Arashiyama bamboo grove"],"ru":["Рёкан с онсэном в Хаконэ","Скоростной синкансэн","Частная чайная церемония","Бамбуковая роща Арасияма"]}'::jsonb, '{"en":["4★ hotels and one ryokan night","7-day Japan Rail Pass","Expert tour leader","Tea ceremony and temple entries","Breakfasts and four dinners"],"ru":["4★ отели и ночь в рёкане","JR Pass на 7 дней","Опытный руководитель группы","Чайная церемония и входы в храмы","Завтраки и четыре ужина"]}'::jsonb, '{"en":["International flights","Japan visa (if required)","Lunches","Travel insurance"],"ru":["Международные перелёты","Виза в Японию (если нужна)","Обеды","Страховка"]}'::jsonb, '[{"day":"1–3","stop":"Tokyo","title":{"en":"Tokyo","ru":"Токио"},"text":{"en":"Asakusa, Meiji shrine, Shibuya crossing and an izakaya evening.","ru":"Асакуса, храм Мэйдзи, перекрёсток Сибуя и вечер в идзакае."}},{"day":"4","stop":"Hakone","title":{"en":"Hakone & Fuji","ru":"Хаконэ и Фудзи"},"text":{"en":"Lake Ashi cruise, ropeway and a kaiseki dinner at a ryokan.","ru":"Круиз по озеру Аси, канатная дорога и кайсэки-ужин в рёкане."}},{"day":"5–8","stop":"Kyoto","title":{"en":"Kyoto","ru":"Киото"},"text":{"en":"Fushimi Inari, Gion, Arashiyama, Philosopher’s Path in bloom.","ru":"Фусими Инари, Гион, Арасияма, Тропа философа в цвету."}},{"day":"9","stop":"Nara","title":{"en":"Nara","ru":"Нара"},"text":{"en":"Todai-ji temple and the deer park.","ru":"Храм Тодай-дзи и парк оленей."}},{"day":"10","stop":"Osaka","title":{"en":"Departure","ru":"Отъезд"},"text":{"en":"Transfer to Kansai airport.","ru":"Трансфер в аэропорт Кансай."}}]'::jsonb, '["Tokyo","Hakone","Kyoto","Nara","Osaka"]'::jsonb, 'guide-haruka-n', '["https://images.unsplash.com/photo-1490806843957-31f4c9a91c65?auto=format&fit=crop&w=1600&q=75","https://images.unsplash.com/photo-1545569341-9eb8b30979d9?auto=format&fit=crop&w=1600&q=75","https://images.unsplash.com/photo-1493976040374-85c8e12f0c0e?auto=format&fit=crop&w=1600&q=75","https://images.unsplash.com/photo-1540959733332-eab4deabeeaf?auto=format&fit=crop&w=1600&q=75","https://images.unsplash.com/photo-1528360983277-13d401cdc186?auto=format&fit=crop&w=1600&q=75"]'::jsonb, '["2027-03-25","2027-04-01","2027-04-08","2027-10-28","2027-11-11"]'::jsonb, '{"min":6,"max":14}'::jsonb, 'japan', 'cultural', 'group', 'easy', 10, 4250, 4.9, 89, 92, true, false),
  ('tour-dubai', 'dubai-desert-luxury', '{"en":"Dubai Desert & Skyline Luxury","ru":"Дубай: пустыня и небоскрёбы","ky":"Дубай: чөл жана асман тиреген имараттар"}'::jsonb, '{"en":"Dubai, United Arab Emirates","ru":"Дубай, ОАЭ","ky":"Дубай, БАЭ"}'::jsonb, '{"en":"A beachfront resort, sunset dunes with a private desert camp and the view from the world’s tallest tower.","ru":"Курорт на первой линии, закат в дюнах с частным лагерем и вид с самой высокой башни мира.","ky":"Деңиз жээгиндеги курорт, жеке чөл лагери менен кумдуу дөбөлөрдөгү күн батыш жана дүйнөдөгү эң бийик мунарадан көрүнүш."}'::jsonb, '{"en":"A polished city-and-desert escape. Stay on the beach in a five-star resort, see the city from the top of Burj Khalifa, explore the old souks of Deira by abra, and spend an evening in the Dubai Desert Conservation Reserve with falconry, a private dinner and stargazing.","ru":"Изысканный отдых между городом и пустыней. Пятизвёздочный курорт на пляже, город с вершины Бурдж-Халифы, старые рынки Дейры на абре и вечер в заповеднике пустыни с соколиной охотой, частным ужином и звёздным небом."}'::jsonb, '{"en":["Private desert dinner & falconry","Burj Khalifa at sunset","Five-star beach resort","Abra ride to the old souks"],"ru":["Частный ужин в пустыне и соколы","Бурдж-Халифа на закате","Пятизвёздочный пляжный курорт","Абра к старым рынкам"]}'::jsonb, '{"en":["Five-star beach resort","Private chauffeur throughout","Burj Khalifa tickets","Private desert experience","Daily breakfast"],"ru":["Пятизвёздочный пляжный курорт","Личный шофёр","Билеты на Бурдж-Халифу","Частная программа в пустыне","Завтраки"]}'::jsonb, '{"en":["International flights","UAE visa (if required)","Tourism dirham fee","Travel insurance"],"ru":["Международные перелёты","Виза ОАЭ (если нужна)","Туристический сбор","Страховка"]}'::jsonb, '[{"day":"1","stop":"Dubai Marina","title":{"en":"Arrival","ru":"Прибытие"},"text":{"en":"Chauffeur transfer to a beach resort, evening at leisure.","ru":"Трансфер с шофёром на пляжный курорт, свободный вечер."}},{"day":"2","stop":"Downtown","title":{"en":"Old & new Dubai","ru":"Старый и новый Дубай"},"text":{"en":"Al Fahidi, abra crossing, souks and Burj Khalifa at sunset.","ru":"Аль-Фахиди, абра, рынки и Бурдж-Халифа на закате."}},{"day":"3","stop":"Desert Reserve","title":{"en":"Desert evening","ru":"Вечер в пустыне"},"text":{"en":"Dune drive, falconry show and private dinner under the stars.","ru":"Поездка по дюнам, соколиная охота и частный ужин под звёздами."}},{"day":"4","stop":"Abu Dhabi","title":{"en":"Abu Dhabi day","ru":"День в Абу-Даби"},"text":{"en":"Sheikh Zayed Grand Mosque and Louvre Abu Dhabi.","ru":"Мечеть шейха Зайда и Лувр Абу-Даби."}},{"day":"5","stop":"Dubai Marina","title":{"en":"Departure","ru":"Отъезд"},"text":{"en":"Late checkout and private airport transfer.","ru":"Поздний выезд и трансфер в аэропорт."}}]'::jsonb, '["Dubai Marina","Downtown","Desert Reserve","Abu Dhabi"]'::jsonb, 'guide-omar-h', '["https://images.unsplash.com/photo-1512453979798-5ea266f8880c?auto=format&fit=crop&w=1600&q=75","https://images.unsplash.com/photo-1518684079-3c830dcef090?auto=format&fit=crop&w=1600&q=75","https://images.unsplash.com/photo-1546412414-e1885259563a?auto=format&fit=crop&w=1600&q=75","https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=1600&q=75"]'::jsonb, '["2027-01-14","2027-02-11","2027-03-11","2027-10-14","2027-11-18","2027-12-09"]'::jsonb, '{"min":1,"max":6}'::jsonb, 'uae', 'luxury', 'private', 'easy', 5, 2190, 4.7, 112, 87, false, false),
  ('tour-samarkand-bukhara', 'samarkand-bukhara-silk-road', '{"en":"Samarkand & Bukhara: Silk Road Cities","ru":"Самарканд и Бухара: города Шёлкового пути","ky":"Самарканд жана Бухара: Жибек жолунун шаарлары"}'::jsonb, '{"en":"Tashkent, Samarkand & Bukhara, Uzbekistan","ru":"Ташкент, Самарканд и Бухара, Узбекистан","ky":"Ташкент, Самарканд жана Бухара, Өзбекстан"}'::jsonb, '{"en":"The blue domes of the Registan, the old town of Bukhara and the high-speed Afrosiyob train — a weekly group tour.","ru":"Голубые купола Регистана, старая Бухара и скоростной «Афросиаб» — групповой тур с выездами каждую неделю.","ky":"Регистандын көк куполдору, эски Бухара жана ылдам «Афросиаб» поезди — ар жумада чыгуучу топтук тур."}'::jsonb, '{"en":"Five days along the Great Silk Road. Walk the Registan at sunset and again when it is lit at night, visit the Gur-Emir mausoleum and Shah-i-Zinda necropolis in Samarkand, then continue by train to Bukhara: the Ark fortress, Poi-Kalyan and the trading domes of the old city. Plenty of time for plov, bazaars and photographs.","ru":"Пять дней по Великому шёлковому пути. Регистан на закате и в ночной подсветке, мавзолей Гур-Эмир и некрополь Шахи-Зинда в Самарканде, затем поездом в Бухару: крепость Арк, ансамбль Пои-Калян и торговые купола старого города. Много времени на плов, базары и фотографии."}'::jsonb, '{"en":["Registan by day and by night","Afrosiyob high-speed train","Old Bukhara and the Ark fortress","Uzbek plov and bazaars"],"ru":["Регистан днём и ночью","Скоростной поезд «Афросиаб»","Старая Бухара и крепость Арк","Узбекский плов и базары"]}'::jsonb, '{"en":["Hotels in Tashkent, Samarkand and Bukhara","Train tickets between cities","Guided excursions","Breakfasts","Tour leader throughout"],"ru":["Отели в Ташкенте, Самарканде и Бухаре","Ж/д билеты между городами","Экскурсии с гидом","Завтраки","Сопровождающий на всём маршруте"]}'::jsonb, '{"en":["Travel to Tashkent","Lunches and dinners","Entrance tickets to monuments","Travel insurance"],"ru":["Дорога до Ташкента","Обеды и ужины","Входные билеты в памятники","Страховка"]}'::jsonb, '[{"day":"1","stop":"Tashkent","title":{"en":"Arrival in Tashkent","ru":"Прибытие в Ташкент"},"text":{"en":"Meet the group, evening walk and dinner.","ru":"Встреча группы, вечерняя прогулка и ужин."}},{"day":"2","stop":"Samarkand","title":{"en":"Train to Samarkand","ru":"Поезд в Самарканд"},"text":{"en":"Registan, Gur-Emir and the Registan light show.","ru":"Регистан, Гур-Эмир и вечернее шоу на Регистане."}},{"day":"3","stop":"Samarkand","title":{"en":"Shah-i-Zinda & Siab bazaar","ru":"Шахи-Зинда и Сиабский базар"},"text":{"en":"Necropolis, Bibi-Khanym mosque and the old bazaar.","ru":"Некрополь, мечеть Биби-Ханым и старый базар."}},{"day":"4","stop":"Bukhara","title":{"en":"Bukhara old town","ru":"Старая Бухара"},"text":{"en":"Ark fortress, Poi-Kalyan, Lyabi-Hauz and the trading domes.","ru":"Крепость Арк, Пои-Калян, Ляби-Хауз и торговые купола."}},{"day":"5","stop":"Tashkent","title":{"en":"Return","ru":"Возвращение"},"text":{"en":"Train back to Tashkent and departure.","ru":"Поезд в Ташкент и отъезд."}}]'::jsonb, '["Tashkent","Samarkand","Bukhara"]'::jsonb, null, '["https://images.unsplash.com/photo-1733586092622-1b3201e802a5?auto=format&fit=crop&w=1600&q=75","https://images.unsplash.com/photo-1763144967763-2a8a98cb8431?auto=format&fit=crop&w=1600&q=75","https://images.unsplash.com/photo-1677156811762-842312963ecd?auto=format&fit=crop&w=1600&q=75","https://images.unsplash.com/photo-1774810307189-5c43a4f46cc5?auto=format&fit=crop&w=1600&q=75","https://images.unsplash.com/photo-1758766182810-773ef5bdada8?auto=format&fit=crop&w=1600&q=75","https://images.unsplash.com/photo-1670514535515-e7af911bdadb?auto=format&fit=crop&w=1600&q=75"]'::jsonb, '["2026-11-20","2026-11-27","2026-12-04","2026-12-11","2026-12-18","2026-12-25","2027-01-01","2027-01-08","2027-01-15","2027-01-22","2027-01-29","2027-02-05","2027-02-12","2027-02-19","2027-02-26","2027-03-05","2027-03-12","2027-03-19","2027-03-26","2027-04-02","2027-04-09","2027-04-16","2027-04-23","2027-04-30","2027-05-07","2027-05-14"]'::jsonb, '{"min":4,"max":18}'::jsonb, 'uzbekistan', 'cultural', 'group', 'easy', 5, 590, 4.9, 0, 99, true, true),
  ('tour-almaty', 'almaty-charyn-big-almaty-lake', '{"en":"Almaty, Charyn Canyon & Big Almaty Lake","ru":"Алматы, Чарынский каньон и БАО","ky":"Алматы, Чарын капчыгайы жана Чоң Алматы көлү"}'::jsonb, '{"en":"Almaty region, Kazakhstan","ru":"Алматинская область, Казахстан","ky":"Алматы облусу, Казакстан"}'::jsonb, '{"en":"A weekend from Bishkek: the red walls of Charyn Canyon, the turquoise Big Almaty Lake and the city lights from Kok-Tobe.","ru":"Выходные из Бишкека: красные стены Чарынского каньона, бирюзовое Большое Алматинское озеро и огни города с Кок-Тобе.","ky":"Бишкектен дем алыш күндөрү: Чарын капчыгайынын кызыл дубалдары, көгүлтүр Чоң Алматы көлү жана Көк-Төбөдөн шаардын жарыктары."}'::jsonb, '{"en":"A compact weekend trip to Almaty. Walk the Valley of Castles in Charyn Canyon, drive up to the turquoise Big Almaty Lake in the Ile-Alatau mountains, and spend an evening in the city with the view from Kok-Tobe. Departures every week.","ru":"Компактный тур выходного дня в Алматы. Прогулка по Долине замков Чарынского каньона, подъём к бирюзовому Большому Алматинскому озеру в горах Иле-Алатау и вечер в городе с видом с Кок-Тобе. Выезды каждую неделю."}'::jsonb, '{"en":["Valley of Castles, Charyn Canyon","Big Almaty Lake","Kok-Tobe viewpoint","Weekly departures from Bishkek"],"ru":["Долина замков, Чарынский каньон","Большое Алматинское озеро","Смотровая Кок-Тобе","Выезды из Бишкека каждую неделю"]}'::jsonb, '{"en":["Transport from and to Bishkek","Hotel in Almaty","Guide","National park fees"],"ru":["Трансфер из Бишкека и обратно","Отель в Алматы","Гид","Сборы нацпарков"]}'::jsonb, '{"en":["Meals","Kok-Tobe cable car","Travel insurance"],"ru":["Питание","Канатная дорога на Кок-Тобе","Страховка"]}'::jsonb, '[{"day":"1","stop":"Almaty","title":{"en":"Bishkek → Almaty","ru":"Бишкек → Алматы"},"text":{"en":"Morning transfer across the border, evening on Kok-Tobe.","ru":"Утренний переезд через границу, вечер на Кок-Тобе."}},{"day":"2","stop":"Charyn","title":{"en":"Charyn Canyon","ru":"Чарынский каньон"},"text":{"en":"Full day in the Valley of Castles and by the Charyn river.","ru":"Целый день в Долине замков и у реки Чарын."}},{"day":"3","stop":"Big Almaty Lake","title":{"en":"Big Almaty Lake & return","ru":"БАО и возвращение"},"text":{"en":"Morning at the lake, then back to Bishkek.","ru":"Утро у озера, затем возвращение в Бишкек."}}]'::jsonb, '["Almaty","Charyn","Big Almaty Lake"]'::jsonb, null, '["https://images.unsplash.com/photo-1572940734104-684309ed7ac9?auto=format&fit=crop&w=1600&q=75","https://images.unsplash.com/photo-1607644546432-45b4e524dd3d?auto=format&fit=crop&w=1600&q=75","https://images.unsplash.com/photo-1659651117607-d2b397cf100f?auto=format&fit=crop&w=1600&q=75","https://images.unsplash.com/photo-1752583987964-dcb03772a03e?auto=format&fit=crop&w=1600&q=75","https://images.unsplash.com/photo-1780511441407-a681291fd95f?auto=format&fit=crop&w=1600&q=75"]'::jsonb, '["2026-11-21","2026-11-28","2026-12-05","2026-12-12","2026-12-19","2026-12-26","2027-01-02","2027-01-09","2027-01-16","2027-01-23","2027-01-30","2027-02-06","2027-02-13","2027-02-20","2027-02-27","2027-03-06","2027-03-13","2027-03-20","2027-03-27","2027-04-03","2027-04-10","2027-04-17","2027-04-24","2027-05-01","2027-05-08","2027-05-15"]'::jsonb, '{"min":4,"max":18}'::jsonb, 'kazakhstan', 'nature', 'group', 'easy', 3, 240, 4.8, 0, 97, true, true),
  ('tour-karakol-ski', 'karakol-ski-weekend', '{"en":"Karakol Ski Weekend","ru":"Горнолыжные выходные в Караколе","ky":"Караколдо тоо лыжа дем алышы"}'::jsonb, '{"en":"Karakol, Issyk-Kul region","ru":"Каракол, Иссык-Кульская область","ky":"Каракол, Ысык-Көл облусу"}'::jsonb, '{"en":"Powder snow and spruce forests at Karakol ski base — skiing or snowboarding for every level, every weekend in season.","ru":"Пушистый снег и ельники горнолыжной базы Каракол — лыжи и сноуборд для любого уровня, каждые выходные в сезон.","ky":"Каракол тоо лыжа базасынын жумшак кары жана карагайлары — ар бир деңгээл үчүн лыжа жана сноуборд, сезондо ар дем алышта."}'::jsonb, '{"en":"Leave Bishkek on Friday evening and spend two full days on the slopes of Karakol, the largest ski resort in Kyrgyzstan, with tree-lined runs and views over Issyk-Kul. Beginners can book lessons; equipment hire is available at the base.","ru":"Выезд из Бишкека в пятницу вечером и два полных дня на склонах Каракола — крупнейшего горнолыжного курорта Кыргызстана с трассами среди елей и видом на Иссык-Куль. Для новичков — инструкторы, прокат снаряжения на базе."}'::jsonb, '{"en":["Two full days on the slopes","Runs through spruce forest","Instructors for beginners","Hot springs option"],"ru":["Два полных дня катания","Трассы среди ельников","Инструкторы для новичков","Горячие источники по желанию"]}'::jsonb, '{"en":["Transport from and to Bishkek","Guesthouse accommodation","Breakfasts","Tour leader"],"ru":["Трансфер из Бишкека и обратно","Проживание в гостевом доме","Завтраки","Сопровождающий"]}'::jsonb, '{"en":["Ski pass","Equipment hire and lessons","Lunches and dinners","Insurance"],"ru":["Ски-пасс","Прокат снаряжения и инструктор","Обеды и ужины","Страховка"]}'::jsonb, '[{"day":"1","stop":"Bishkek","title":{"en":"Night transfer","ru":"Ночной переезд"},"text":{"en":"Friday evening departure to Karakol, check-in at a guesthouse.","ru":"Выезд в пятницу вечером в Каракол, заселение в гостевой дом."}},{"day":"2","stop":"Karakol","title":{"en":"Ski day","ru":"День катания"},"text":{"en":"Full day on the slopes; evening in the hot springs (optional).","ru":"Целый день на склонах, вечером — горячие источники (по желанию)."}},{"day":"3","stop":"Bishkek","title":{"en":"Ski & return","ru":"Катание и возвращение"},"text":{"en":"Morning skiing, afternoon drive back to Bishkek.","ru":"Утреннее катание и возвращение в Бишкек."}}]'::jsonb, '["Bishkek","Karakol"]'::jsonb, null, '["https://images.unsplash.com/photo-1639933319952-715226889d30?auto=format&fit=crop&w=1600&q=75","https://images.unsplash.com/photo-1665990452167-55c2061661be?auto=format&fit=crop&w=1600&q=75","https://images.unsplash.com/photo-1595686528907-725bf013cbfd?auto=format&fit=crop&w=1600&q=75","https://images.unsplash.com/photo-1639936014191-130ed8733401?auto=format&fit=crop&w=1600&q=75"]'::jsonb, '["2026-12-11","2026-12-18","2026-12-25","2027-01-01","2027-01-08","2027-01-15","2027-01-22","2027-01-29","2027-02-05","2027-02-12","2027-02-19","2027-02-26","2027-03-05","2027-03-12"]'::jsonb, '{"min":6,"max":20}'::jsonb, 'kyrgyzstan', 'adventure', 'group', 'moderate', 3, 210, 4.9, 0, 95, true, true),
  ('tour-new-year', 'new-year-issyk-kul', '{"en":"New Year in the Mountains of Issyk-Kul","ru":"Новый год в горах Иссык-Куля","ky":"Ысык-Көлдүн тоолорунда Жаңы жыл"}'::jsonb, '{"en":"Issyk-Kul, Kyrgyzstan","ru":"Иссык-Куль, Кыргызстан","ky":"Ысык-Көл, Кыргызстан"}'::jsonb, '{"en":"Celebrate New Year by the warm lake that never freezes — a festive dinner, fireworks and snowy mountains.","ru":"Встретьте Новый год у тёплого незамерзающего озера — праздничный ужин, фейерверк и заснеженные горы.","ky":"Жаңы жылды тоңбогон жылуу көлдүн жээгинде тосуңуз — майрамдык кечки тамак, фейерверк жана карлуу тоолор."}'::jsonb, '{"en":"Three festive days on Issyk-Kul over the New Year holidays: a celebration dinner with music and fireworks at midnight, a walk in the winter mountains, and a visit to the hot springs. A cheerful group tour — perfect for friends and families.","ru":"Три праздничных дня на Иссык-Куле в новогодние каникулы: торжественный ужин с музыкой и фейерверком в полночь, прогулка по зимним горам и горячие источники. Весёлый групповой тур для друзей и семей."}'::jsonb, '{"en":["New Year dinner & fireworks","Winter mountains","Hot springs","Group celebration"],"ru":["Новогодний ужин и фейерверк","Зимние горы","Горячие источники","Праздник в компании"]}'::jsonb, '{"en":["Transport from and to Bishkek","Accommodation","Festive New Year dinner","Tour leader"],"ru":["Трансфер из Бишкека и обратно","Проживание","Праздничный новогодний ужин","Сопровождающий"]}'::jsonb, '{"en":["Other meals","Hot springs entry","Insurance"],"ru":["Остальное питание","Вход в горячие источники","Страховка"]}'::jsonb, '[{"day":"1","stop":"Issyk-Kul","title":{"en":"Arrival on the lake","ru":"Прибытие на озеро"},"text":{"en":"Transfer from Bishkek and check-in.","ru":"Трансфер из Бишкека и заселение."}},{"day":"2","stop":"Issyk-Kul","title":{"en":"New Year’s Eve","ru":"Новогодняя ночь"},"text":{"en":"Winter walk, festive dinner and midnight fireworks.","ru":"Зимняя прогулка, праздничный ужин и фейерверк в полночь."}},{"day":"3","stop":"Bishkek","title":{"en":"Hot springs & return","ru":"Источники и возвращение"},"text":{"en":"Relax in the hot springs, return to Bishkek.","ru":"Отдых в горячих источниках, возвращение в Бишкек."}}]'::jsonb, '["Issyk-Kul","Bishkek"]'::jsonb, null, '["https://images.unsplash.com/photo-1595686528907-725bf013cbfd?auto=format&fit=crop&w=1600&q=75","https://images.unsplash.com/photo-1626767507695-7165523a5372?auto=format&fit=crop&w=1600&q=75","https://images.unsplash.com/photo-1639936014191-130ed8733401?auto=format&fit=crop&w=1600&q=75","https://images.unsplash.com/photo-1694167232441-fd7a2c238d19?auto=format&fit=crop&w=1600&q=75"]'::jsonb, '["2026-12-30"]'::jsonb, '{"min":8,"max":30}'::jsonb, 'kyrgyzstan', 'nature', 'group', 'easy', 3, 320, 5, 0, 93, true, true)
insert into public.reviews (id, name, country, tour_slug, rating, date, text, avatar, photo, status) values
  ('rev-1', 'Sophie L.', 'France', 'song-kul-nomad-journey', 5, '2026-08-19', 'Waking up at Song-Kul with horses grazing outside the yurt is a memory I will keep forever. Every detail was handled, yet it never felt like a package tour.', 'https://images.unsplash.com/photo-1438761681033-6461ffad8d80?auto=format&fit=crop&w=200&q=75', 'https://images.unsplash.com/photo-1489421382202-f7ec0cfd96f7?auto=format&fit=crop&w=900&q=75', 'published'),
  ('rev-2', 'Дмитрий К.', 'Казахстан', 'ala-kul-alpine-lake-trek', 5, '2026-08-02', 'Сложный, но невероятно красивый маршрут. Гид следил за темпом группы и самочувствием каждого. Горячие источники в конце — лучшая награда.', 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=200&q=75', 'https://images.unsplash.com/photo-1721901194224-d91f30cbeac5?auto=format&fit=crop&w=900&q=75', 'published'),
  ('rev-3', 'Айпери Ж.', 'Кыргызстан', 'samarkand-bukhara-silk-road', 5, '2026-10-03', 'Регистанды түнкү жарыкта көргөндө сөз таппай калдым. Уюштуруу абдан жакшы, поезддер ыңгайлуу, мейманканалар таза. Рахмат, Lovi moment!', 'https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&w=200&q=75', 'https://images.unsplash.com/photo-1677156811762-842312963ecd?auto=format&fit=crop&w=900&q=75', 'published'),
  ('rev-4', 'Елена В.', 'Россия', 'almaty-charyn-big-almaty-lake', 5, '2026-09-21', 'За выходные успели и Чарынский каньон, и БАО — очень насыщенно, но без суеты. Сопровождающий всё объяснял, граница прошла быстро.', 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?auto=format&fit=crop&w=200&q=75', 'https://images.unsplash.com/photo-1607644546432-45b4e524dd3d?auto=format&fit=crop&w=900&q=75', 'published'),
  ('rev-5', 'Markus H.', 'Germany', 'issyk-kul-karakol-escape', 4, '2026-07-28', 'A perfect first taste of Kyrgyzstan. The lake is unreal — snowy peaks on one side, beaches on the other. The roads are long, but the guide made every hour interesting.', 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?auto=format&fit=crop&w=200&q=75', 'https://images.unsplash.com/photo-1626767507695-7165523a5372?auto=format&fit=crop&w=900&q=75', 'published'),
  ('rev-6', 'Азамат Т.', 'Кыргызстан', 'karakol-ski-weekend', 5, '2026-02-16', 'Отличные выходные: снег пушистый, трассы среди елей, компания весёлая. Уже записался на следующий выезд!', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=200&q=75', 'https://images.unsplash.com/photo-1639933319952-715226889d30?auto=format&fit=crop&w=900&q=75', 'published'),
  ('rev-7', 'Aiko T.', 'Singapore', 'samarkand-bukhara-silk-road', 5, '2026-10-15', 'Samarkand and Bukhara in five days without any stress — trains, hotels and guides all arranged. The tilework is even more beautiful in person.', 'https://images.unsplash.com/photo-1438761681033-6461ffad8d80?auto=format&fit=crop&w=200&q=75', 'https://images.unsplash.com/photo-1774810307189-5c43a4f46cc5?auto=format&fit=crop&w=900&q=75', 'published'),
  ('rev-8', 'Нурлан А.', 'Кыргызстан', 'new-year-issyk-kul', 5, '2026-01-03', 'Встретили Новый год всей семьёй на Иссык-Куле — праздничный ужин, фейерверк и горячие источники на следующий день. Дети в восторге.', 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=200&q=75', 'https://images.unsplash.com/photo-1595686528907-725bf013cbfd?auto=format&fit=crop&w=900&q=75', 'published')
